set local search_path = public, extensions;create extension if not exists pgtap with schema extensions;select plan(12);select has_table('public','contract_generation_runs','Generation runs are observable');select has_column('public','contract_generation_runs','candidate_count','Candidate count is bounded');select has_column('public','contract_generation_runs','timeout_ms','Timeout is explicit');select has_column('public','contract_generation_runs','maximum_attempts','Retries are bounded');select has_column('public','contract_generation_runs','cost_usd','Cost is measured');select has_table('public','contract_generation_candidates','Candidates persist privately');select has_column('public','contract_generation_candidates','contract_id','Every candidate links to contract');select has_column('public','contract_generation_candidates','prompt_version','Prompt is stamped');select has_column('public','contract_generation_candidates','taxonomy_release_id','Taxonomy is stamped');select has_column('public','contract_generation_candidates','student_visible','Visibility is fail-closed');select has_trigger('public','contract_generation_candidates','immutable_generation_candidate','Candidate content is immutable');select col_is_unique('public','contract_generation_candidates',array['idempotency_key'],'Candidate retries are idempotent');select * from finish();rollback;
